@dataclass(kw_only=True, slots=True)
class EntitiesSetProperties(_Model):
    """Input of `cad.entities.set` v1: properties set for objects named by their
    persistent ids (docs/adr/0014), written as one undo step named after
    `operation`. Everything the command depends on is here (TODOS.md CMD-07):
    Öznitelikler fills `uids` from the selection and the property from the
    row; the command reads no selection, library or view.

    A property absent from the input stays as it is (`unlink`: false). `color`, `lineWeight`,
    `symbol` and `label` are removed with null: the object is drawn in its
    layer's colour, weight and style again, and shows no label. An attribute is set by its name, or
    removed with null; the attributes not named stay. What an object already
    has is not a change: an object as the input asks is left alone and is
    not in the output, and when no object changes nothing is written (no
    undo step, the revision stays).

    An object on a locked layer (by itself or a group above it) is not
    changed (docs/adr/0278): the others are, and the warning `layer_locked`
    counts it; when every one is locked nothing is written and the answer is
    `layer_locked`. No object moves to a locked layer (`layer_locked`).
    Objects move to a hidden layer with the warning `layer_hidden`.

    Refusals (`CommandError.code`), checked in this order: `no_entities`,
    `invalid_uid` (each id in order), `nothing_to_set` (no property given),
    `invalid_attribute` (an attribute name empty or only white space),
    `invalid_line_weight` (a weight not a number from 0 to 100 mm),
    `invalid_line_type_scale` (a scale not above 0 or above 1000),
    `invalid_transparency` (a transparency not from 0 to 0.9),
    `invalid_attachments` (`attachments_problem`, docs/adr/0225 §1), then
    `invalid_revision`, `revision_conflict` (status `conflict`),
    `entity_not_found` (each id in order), `unknown_asset` (an embedded
    photo whose asset is not an image of the project's library, in the
    attachments' order), `layer_not_found` and
    `not_a_layer` (the `layerId` given), `layer_locked` (every object on a
    locked layer: the first one's, in the input's order; then the `layerId` given), then `invalid_attribute`
    and `attribute_required` (the attributes given, by the fields of each
    object's layer, the one it moves to else its own, objects in the input's
    order, names in theirs, at `attrs.<name>`; docs/adr/0199 §2). Warning:
    `layer_hidden` (the `layerId` given is hidden and at least one object
    moves to it).

    A layer with fields (docs/adr/0199 §2): a value given to a field's key is
    written in its canonical text; a value that does not keep the field's
    rules is refused (`invalid_attribute`), an empty or removed one of a
    required field too (`attribute_required`). Keys no field names are free.
    White space is Unicode's `White_Space` (Rust's `char::is_whitespace`).
    Attributes:
        uids: The objects' persistent ids (lowercase UUID text with hyphens), at
            least one; a repeated one counts once.
        operation: What the change is; it names the undo step.
        attachments: Their photos and documents (`EntityBase.attachments`, docs/adr/0225
            §1), the whole list; empty: none. Absent: unchanged.
        attrs: Attributes by name, text in v1: a text sets the attribute (added when
            an object lacks it), null removes it. Absent or empty: none change.
        color: Their own colour (`EntityBase.color`, as `#E5484D`); null: their
            layer's (katmana göre). Absent: unchanged.
        expected_revision: The document revision the input was prepared against, as decimal text
            (from a plan, or the document). When given and the document is no
            longer at it, nothing is written and the answer is `conflict`.
        label: The text shown beside them (`EntityBase.label`); null: none. Absent:
            unchanged.
        layer_id: The layer they move to: a layer's id (`LayerNode.id`), not a group's.
            Absent: they stay on theirs.
        line_type: Their own line type (`ObjectLook.line_type`, docs/adr/0260 §2); null:
            their source's (katmana göre). Absent: unchanged.
        line_type_scale: Their pattern's own factor, above 0, at most 1000; null: 1. Absent: unchanged. Unit: 1.
        line_weight: Their own line weight, paper mm (`EntityBase.line_weight`, 0 the
            thinnest, at most 100); null: their layer's (katmana göre). Absent:
            unchanged. Unit: paper-mm.
        symbol: Their own symbol, a library item's id (`EntityBase.symbol`), drawn
            instead of their layer's style; null: the layer's style. The id is
            not looked up: the libraries are the host's. Absent: unchanged.
        transparency: Their own transparency, 0 to 0.9 (docs/adr/0260 §3); null: their
            source's. Absent: unchanged. Unit: 1.
        unlink: Bağı kopar (docs/adr/0175 §4): `true` breaks the link of the texts
            among them that write an object's label (`TextEntity.label_of` and
            `label_scale` removed); they stay where and as they are and follow
            nothing. Other objects are left alone. Absent or false: unchanged.
    """
    uids: list[str]
    operation: PropertiesOperation | PropertiesOperationName
    attachments: list[Attachment] | None | Unset = UNSET
    attrs: dict[str, str | None] | None | Unset = UNSET
    color: str | None | Unset = UNSET
    expected_revision: str | None | Unset = UNSET
    label: str | None | Unset = UNSET
    layer_id: str | None | Unset = UNSET
    line_type: LineType | LineTypeName | None | Unset = UNSET
    line_type_scale: float | None | Unset = UNSET
    line_weight: float | None | Unset = UNSET
    symbol: str | None | Unset = UNSET
    transparency: float | None | Unset = UNSET
    unlink: bool | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["uids"] = list(self.uids)
        out["operation"] = _enum_out(self.operation)
        if self.attachments is not UNSET:
            out["attachments"] = None if self.attachments is None else [e0.to_json() for e0 in self.attachments]
        if self.attrs is not UNSET:
            out["attrs"] = None if self.attrs is None else dict(self.attrs)
        if self.color is not UNSET:
            out["color"] = self.color
        if self.expected_revision is not UNSET:
            out["expectedRevision"] = self.expected_revision
        if self.label is not UNSET:
            out["label"] = self.label
        if self.layer_id is not UNSET:
            out["layerId"] = self.layer_id
        if self.line_type is not UNSET:
            out["lineType"] = None if self.line_type is None else _enum_out(self.line_type)
        if self.line_type_scale is not UNSET:
            out["lineTypeScale"] = None if self.line_type_scale is None else float(self.line_type_scale)
        if self.line_weight is not UNSET:
            out["lineWeight"] = None if self.line_weight is None else float(self.line_weight)
        if self.symbol is not UNSET:
            out["symbol"] = self.symbol
        if self.transparency is not UNSET:
            out["transparency"] = None if self.transparency is None else float(self.transparency)
        if self.unlink is not UNSET:
            out["unlink"] = self.unlink
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> EntitiesSetProperties:
        return cls(
            uids=list(data["uids"]),
            operation=_enum_in(PropertiesOperation, data["operation"]),
            attachments=UNSET if "attachments" not in data else None if data["attachments"] is None else [Attachment.from_json(e0) for e0 in data["attachments"]],
            attrs=UNSET if "attrs" not in data else None if data["attrs"] is None else dict(data["attrs"]),
            color=data.get("color", UNSET),
            expected_revision=data.get("expectedRevision", UNSET),
            label=data.get("label", UNSET),
            layer_id=data.get("layerId", UNSET),
            line_type=UNSET if "lineType" not in data else None if data["lineType"] is None else _enum_in(LineType, data["lineType"]),
            line_type_scale=UNSET if "lineTypeScale" not in data else None if data["lineTypeScale"] is None else float(data["lineTypeScale"]),
            line_weight=UNSET if "lineWeight" not in data else None if data["lineWeight"] is None else float(data["lineWeight"]),
            symbol=data.get("symbol", UNSET),
            transparency=UNSET if "transparency" not in data else None if data["transparency"] is None else float(data["transparency"]),
            unlink=data.get("unlink", UNSET),
        )


