    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "object"}
        out["uid"] = self.uid
        out["at"] = _vec2_out(self.at)
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ObjectUcsTo:
        return cls(
            uid=data["uid"],
            at=Vec2.from_json(data["at"]),
        )


