    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {"kind": "rename"}
        out["name"] = self.name
        out["to"] = self.to
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> RenameViewsOp:
        return cls(
            name=data["name"],
            to=data["to"],
        )


